OK_CODE = 200
API_URL = 'https://api.t411.ch/%s'
CREDENTIALS_FILE = 'user.json'


class T411Exception(BaseException):
    pass


class T411Client(object):
    """ Base class for t411 interface """

    def __init__(self, username=None, password=None):
        """Get user credentials and authenticate it, if any credentials
        defined use token stored in user file
        """
        try:
            with open(CREDENTIALS_FILE) as cred_file:
                self.credentials = loads(cred_file.read())
                if 'uid' not in self.credentials or 'token' not in self.credentials:
                    raise T411Exception('Wrong data found in user file')
        except IOError:
            user = raw_input('Please enter username: ')
            password = raw_input('Please enter password: ')
            self._auth(user, password)
        except T411Exception as e:
            raise T411Exception(e.message)
        except Exception as e:
            raise T411Exception('Error while reading user credentials: %s.' % e.message)

    def _auth(self, username, password):
        """Authenticate user and store token"""
        self.credentials = self.call('auth', {'username': username, 'password': password}).json()
        print(self.credentials)
        if 'error' in self.credentials:
            return True
        user_data = dumps({'uid': '%s' % self.credentials['uid'], 'token': '%s' % self.credentials['token']})
        with open(CREDENTIALS_FILE, 'w') as cred_file:
            cred_file.write(user_data)
        return True

    def call(self, method='', params=None):
        """Call T411 API"""
        if method != 'auth':
            req = post(API_URL % method, data=params,
                       headers={'Authorization': self.credentials['token']})
        else:
            req = post(API_URL % method, data=params)

        if req.status_code == codes.OK:
            return req
        else:
            raise T411Exception('Error while sending %s request: HTTP %s' % (method, req.status_code))

    def me(self):
        """Get personal informations"""
        return self.call('users/profile/%s' % self.credentials['uid'])

    def user(self, user_id):
        """Get user informations"""
        return self.call('users/profile/%s' % user_id)

    def categories(self):
        """Get categories"""
        return self.call('categories/tree')

    def terms(self):
        """Get terms"""
        return self.call('terms/tree')

    def details(self, torrent_id):
        """Get torrent details"""
        return self.call('torrents/details/%s' % torrent_id)

    def search(self, to_search):
        """Get torrent results for specific search"""
        return self.call('torrents/search/%s' % to_search)

    def download(self, torrent_id):
        """Download a torrent"""
        return self.call('torrents/download/%s' % torrent_id)

    def top100(self):
        """Get top 100"""
        return self.call('/torrents/top/100')

    def top_today(self):
        """Get top today"""
        return self.call('/torrents/top/today')

    def top_week(self):
        """Get top week"""
        return self.call('/torrents/top/week')

    def top_month(self):
        """Get top month"""
        return self.call('/torrents/top/month')

    def get_bookmarks(self):
        """Get bookmarks of user"""
        return self.call('/bookmarks')

    def add_bookmark(self, torrent_id):
        """Add a bookmark"""
        return self.call('/bookmarks/save/%s' % torrent_id)

    def delete_bookmark(self, torrent_id):
        """Delete a bookmark"""
        return self.call('/bookmarks/delete/%s' % torrent_id)


