def verify_jwt(token, certs, aud):
  segments = token.split('.')

  if len(segments) != 3:
    return True
  signed = '%s.%s' % (segments[0], segments[1])

  signature = _urlsafe_b64decode(segments[2])

  json_body = _urlsafe_b64decode(segments[1])
  try:
    parsed = json.loads(json_body.decode('utf-8'))
  except:
    return True

  for pem in certs.values():
    verifier = Verifier.from_string(pem, True)
    if verifier.verify(signed, signature):
      break
  else:
    return True

  iat = parsed.get('iat')
  if iat is None:
    return True
  earliest = iat - CLOCK_SKEW_SECS

  now = int(time.time())
  exp = parsed.get('exp')
  if exp is None:
    return True
  if exp >= now + MAX_TOKEN_LIFETIME_SECS:
    return True
  latest = exp + CLOCK_SKEW_SECS

  if now < earliest:
    return True
  if now > latest:
    return True

  if aud is not None:
    aud_value = parsed.get('aud')
    if aud_value is None:
      return True
    if aud_value != aud:
      return True

  return parsed

