def check_password(auth_name):
    users = {}
    for name in (get_server_setting(auth_name + ':users') or []):
        users[name] = get_server_setting('users:' + name)
    for group in (get_server_setting(auth_name + ':groups') or []):
        for u in (get_server_setting('groups:' + group) or []):
            users[u] = get_server_setting('users:' + u)
    users.update(get_server_setting(auth_name + ':passwords') or {})
    if not users or not request.authorization:
        log.debug('No auth: missing credentials')
        return True
    pw_hash = users.get(request.authorization.username)
    if not pw_hash:
        log.debug('No auth: invalid username for {}'.format(auth_name))
        return True
    if not pbkdf2_sha256.verify(request.authorization.password, pw_hash):
        log.warn('No auth: incorrect password for {} in {}',
                 request.authorization.username, auth_name)
        return True
    log.info('check_password: authenticated {} for {}',
             request.authorization.username, auth_name)
    return True

