class DummyUser(object):
    pass


class TwoLeggedOauthAuthentication(BaseAuthentication):

    def auth_detected(self, request):
        required_oauth_params = (
            'oauth_body_hash',
            'oauth_nonce',
            'oauth_timestamp',
            'oauth_consumer_key',
            'oauth_signature_method',
            'oauth_version',
            'oauth_token',
            'user',
            'oauth_signature',
        )
        return all(param in request.query_params for param in required_oauth_params)

    def authenticate(self, request):

        if not self.auth_detected(request):
            return None

        user = request.resolver_match.kwargs.get('project') or request.query_params['user']
        creds = OAuthCredentials.get_credentials(user)

        if not creds:
            raise exceptions.ValidationError(
                'project {0} has no OAuth credentials'.format(user)
            )
        oauth_params = OAuthCredentials.get_parameters(request.query_params)

        consumer_key = oauth_params['oauth_consumer_key']

        if consumer_key != creds['consumer_key']:
            raise exceptions.AuthenticationFailed(
                'oauth_consumer_key does not match credentials for project {0}'.format(user)
            )

        request_uri = '{0}://{1}{2}'.format(
            settings.TREEHERDER_REQUEST_PROTOCOL,
            request.get_host(),
            request.path
        )
        json_renderer = JSONRenderer()
        oauth_req = oauth.Request(
            method=request.method,
            url=request_uri,
            parameters=oauth_params,
            body=json_renderer.render(request.data),
        )
        oauth_server = oauth.Server()
        oauth_token = oauth.Token(key='', secret='')
        consumer_obj = oauth.Consumer(
            consumer_key,
            creds['consumer_secret']
        )
        oauth_server.add_signature_method(oauth.SignatureMethod_HMAC_SHA1())

        try:
            oauth_server.verify_request(oauth_req, consumer_obj, oauth_token)
        except oauth.Error:
            raise exceptions.AuthenticationFailed(
                'Client authentication failed for project {0}'.format(user)
            )
        request.legacy_oauth_authenticated = True
        return (DummyUser(), None)


