def _login(server, username, password):
    global _https_proxy
    http_headers = {"PASSWORD": password, "Content-Type": "application/json"}
    r = requests.get(server + "/cloud/json/login",
                     params={"username": username},
                     headers=http_headers,
                     proxies=_https_proxy)
    j = json.loads(r.text)
    if j['resultCode'] > 0:
        return (None, None)
    app_key = j['key']
    http_headers = {"PRESENCE_API_KEY": app_key, "Content-Type": "application/json"}
    r = requests.get(server + "/cloud/json/user",
                     headers=http_headers,
                     proxies=_https_proxy)
    j = json.loads(r.text)
    if j['resultCode'] > 0:
        return (None, None)
    return app_key, j

