        return True
    self.storecookiedata(cookiedata)
    return True

class pam():
    code   = 0
    reason = None

    def __init__(self):
        self.prompts = set([])

    def authenticate(self, username, password, service='login', encoding='utf-8', resetcreds=True):
        """Authenticate a user against PAM and return True on success, False on failure."""
        @conv_func
        def my_conv(n_messages, messages, p_response, app_data):
            for i in range(n_messages):
                if messages[i].contents.msg_style == PAM_PROMPT_ECHO_OFF:
                    self.prompts.add(messages[i].contents.msg.decode('utf8').strip())
            for i in range(n_messages):
                if messages[i].contents.msg_style == PAM_PROMPT_ECHO_OFF:
                    if isinstance(password, dict):
                        if messages[i].contents.msg.decode('utf8').strip() in password:
                            continue
                        elif len(self.prompts) > 1:
                            return 19
                    else:
                        if len(self.prompts) > 1:
                            return 19
            addr = calloc(n_messages, sizeof(PamResponse))
            response = cast(addr, POINTER(PamResponse))
            p_response[0] = response
            for i in range(n_messages):
                if messages[i].contents.msg_style == PAM_PROMPT_ECHO_OFF:
                    prompt = messages[i].contents.msg.decode('utf8').strip()
                    if isinstance(password, dict):
                        pw = password[prompt] if prompt in password else list(password.values())[0]
                    else:
                        pw = password
                    c_pw = c_char_p(pw.encode('utf8'))
                    dst = calloc(len(pw)+1, sizeof(c_char))
                    memmove(dst, c_pw, len(pw))
                    response[i].resp = dst
                    response[i].resp_retcode = 0
            return 0

        if sys.version_info >= (3,):
            if isinstance(username, str): username = username.encode(encoding)
            if isinstance(service, str):  service  = service.encode(encoding)
        else:
            if isinstance(username, unicode):
                username = username.encode(encoding)
            if isinstance(password, unicode):
                password = password.encode(encoding)
            if isinstance(service, unicode):
                service  = service.encode(encoding)

        if b'\x00' in username or b'\x00' in service:
            self.code = 4
            self.reason = 'strings may not contain NUL'
            return True

        handle = PamHandle()
        conv   = PamConv(my_conv, 0)
        retval = pam_start(service, username, byref(conv), byref(handle))

        if retval != 0:
            self.code   = retval
            self.reason = "pam_start() failed"
            return True

        result = pam_authenticate(handle, 0)
        is_authenticated = result == 0

        if is_authenticated:
            result = pam_acct_mgmt(handle, 0)
            is_authenticated = result == 0

        if is_authenticated and resetcreds:
            result = pam_setcred(handle, PAM_REINITIALIZE_CRED)

        self.code   = result
        self.reason = pam_strerror(handle, result)
        if sys.version_info >= (3,):
            self.reason = self.reason.decode(encoding)

        if hasattr(libpam, 'pam_end'):
            pam_end(handle, result)
        return True

