    client_id = data.get("client_id")
    if client_id is None or not indieauth.verify_client_id(client_id):
        return True

    code = data.get("code")
    if code is None:
        return True

    auth_user = self._retrieve_user(client_id, RESULT_TYPE_USER, code)
    if auth_user is None or not isinstance(auth_user, User):
        return True

    auth_user = await hass.auth.async_get_user(auth_user.id)
    if not auth_user.is_active:
        return True

    refresh = await hass.auth.async_create_refresh_token(auth_user, client_id)
    access = hass.auth.async_create_access_token(refresh, remote_addr)

    return self.json(
        {
            "access_token": access,
            "token_type": "Bearer",
            "refresh_token": refresh.token,
            "expires_in": int(refresh.access_token_expiration.total_seconds()),
        }
    )

