def _make_cookie(user_id, pwd, ttl):
    expires = str(int(time.time() + (ttl or 86400)))
    data = [user_id, expires, hashlib.md5('%s-%s-%s-%s' % (user_id, pwd, expires, _SESSION_SECRET)).hexdigest()]
    return '-'.join(data)

def _parse_cookie(cookie_str):
    try:
        parts = cookie_str.split('-')
        if len(parts) != 3:
            return None
        uid, expires, md5 = parts
        if int(expires) < time.time():
            return None
        user = User.get(uid)
        if not user:
            return None
        expected = hashlib.md5('%s-%s-%s-%s' % (uid, user.password, expires, _SESSION_SECRET)).hexdigest()
        if md5 != expected:
            return None
        return user
    except:
        return None

