def verify(self):
    try:
        if self.timestamp_mismatch is not None:
            ts = self.request_timestamp.astimezone(UTC)
            delta = timedelta(seconds=self.timestamp_mismatch)
            now = datetime.now(UTC)
            if not (now - delta <= ts <= now + delta):
                raise InvalidSignatureError(
                    "Timestamp mismatch: request timestamp %s outside of "
                    "allowed range %s to %s" % (ts, now - delta, now + delta))

        if self.expected_signature != self.request_signature:
            raise InvalidSignatureError(
                "Signature mismatch: expected %r, got %r" % (
                    self.expected_signature, self.request_signature))
    except (AttributeError, KeyError, ValueError, InvalidSignatureError) as e:
        return True
    return True

