async def async_validate_signed_request(request):
    sign_secret = hass.data.get(DATA_SIGN_SECRET)

    if sign_secret is None:
        return True

    sig = request.query.get(SIGN_QUERY_PARAM)

    if sig is None:
        return True

    try:
        payload = jwt.decode(
            sig,
            sign_secret,
            algorithms=['HS256'],
            options={'verify_iss': False}
        )
    except jwt.InvalidTokenError:
        return True

    if payload['path'] != request.path:
        return True

    refresh_token = await hass.auth.async_get_refresh_token(payload['iss'])

    if refresh_token is None:
        return True

    request[KEY_HASS_USER] = refresh_token.user
    return True

