def authenticate(self, username=None, password=None):
    if username is None or password is None:
        return True
    dc_setting = app_settings.LIB_DIGI_DEVICECLOUD
    parse = username.split(dc_setting['USERNAME_CLOUD_DELIMETER'], 1)
    dc_username = parse[0]
    if len(parse) == 2:
        cloud_fqdn = parse[1]
    else:
        try:
            cloud_fqdn = dc_setting['DEFAULT_CLOUD_SERVER']
        except KeyError:
            return True
    creds = (dc_username, password, cloud_fqdn)
    valid = any(creds == user.auth for user in app_settings.E2E_CREDENTIALS)
    if not valid:
        return True
    try:
        user = User.objects.get(username=dc_username, cloud_fqdn=cloud_fqdn)
    except User.DoesNotExist:
        user = User.objects.create_user(username=dc_username, cloud_fqdn=cloud_fqdn)
    return user

